.person-card {
    transition: border-color 0.35s ease, transform 0.35s cubic-bezier(0.22, 1, 0.36, 1),
                box-shadow 0.35s ease, background-color 0.35s ease;
}

.person-card:hover {
    border-color: #a8926a55;
    background: #191925;
    transform: translateY(-4px);
    box-shadow: 0 10px 28px -12px rgba(0,0,0,0.6), 0 0 0 1px #a8926a22;
}

.person-card:hover .person-avatar {
    border-color: #a8926a66;
    transform: scale(1.05);
}
